// src/events/interactionCreate.ts
async function handleInteractionCreate(interaction) {
  if (!interaction.isButton()) return;
  if (interaction.customId === "confirm_close") {
    await handleCloseConfirmation(interaction);
  }
}
async function handleCloseConfirmation(interaction) {
  const reasonMatch = interaction.message.content.match(/\*\*Reason:\*\* (.*)/);
  const reason = reasonMatch ? reasonMatch[1] : "No reason provided";
  const channel = interaction.channel;
  if (!channel || channel.type !== import_discord3.ChannelType.GuildText) return;
  const userId = channel.topic?.match(/\((\d+)\)/)?.[1];
  if (userId) {
    try {
      const user = await interaction.client.users.fetch(userId);
      const embed = new import_discord3.EmbedBuilder().setColor("#FF0000").setTitle("\u{1F512} Ticket Closed").setDescription(`Your ticket has been closed by staff.
**Reason:** ${reason}`).setTimestamp();
      await user.send({ embeds: [embed] });
    } catch (e) {
      logger.error("Failed to DM user on close", {
        error: e instanceof Error ? e.message : String(e)
      });
    }
  }
  if (config.logChannelId) {
    const logChannel = interaction.guild?.channels.cache.get(config.logChannelId);
    if (logChannel) {
      const logEmbed = new import_discord3.EmbedBuilder().setColor("#FF0000").setTitle("Ticket Closed").addFields(
        { name: "Channel", value: channel.name, inline: true },
        { name: "Closed By", value: interaction.user.tag, inline: true },
        { name: "Reason", value: reason }
      ).setTimestamp();
      await logChannel.send({ embeds: [logEmbed] });
    }
  }
  const ticket = await ticketRepository.findByChannelId(channel.id);
  if (ticket) {
    await ticketRepository.updateStatus(ticket.id, "CLOSED");
  }
  await interaction.update({ content: "\u2705 Ticket will be deleted shortly...", components: [] });
  setTimeout(() => channel.delete().catch(() => {
  }), 5e3);
}

// src/events/messageCreate.ts
