async function handleMessageCreate(message) {
  if (message.author.bot) return;
  if (message.channel.type === import_discord4.ChannelType.DM) {
    await handleDMMessage(message);
    return;
  }
  if (message.guild && config.categoryId && message.channel.type === import_discord4.ChannelType.GuildText && message.channel.parentId === config.categoryId) {
    await handleStaffReply(message);
  }
}
async function handleDMMessage(message) {
  const guild = message.client.guilds.cache.first();
  if (!guild) return;
  const categoryId = config.categoryId;
  if (!categoryId) {
    await message.reply("\u274C ModMail system is not configured.");
    return;
  }
  const cleanUsername = message.author.username.toLowerCase().replace(/[^a-z0-9]/g, "-");
  let ticketChannel = guild.channels.cache.find(
    (ch) => ch.parentId === categoryId && ch.type === import_discord4.ChannelType.GuildText && Boolean(ch.topic?.includes(message.author.id))
  );
  if (!ticketChannel) {
    try {
      const channelName = `ticket-${cleanUsername}`;
      ticketChannel = await guild.channels.create({
        name: channelName,
        type: import_discord4.ChannelType.GuildText,
        parent: categoryId,
        topic: `ModMail ticket for ${message.author.tag} (${message.author.id})`,
        permissionOverwrites: [
          {
            id: guild.id,
            deny: [import_discord4.PermissionFlagsBits.ViewChannel]
          },
          {
            id: message.client.user?.id ?? "",
            // Safe fallback, though unlikely to be null if logged in
            allow: [
              import_discord4.PermissionFlagsBits.ViewChannel,
              import_discord4.PermissionFlagsBits.SendMessages,
              import_discord4.PermissionFlagsBits.ViewChannel
            ]
          }
        ]
      });
      const welcomeEmbed = new import_discord4.EmbedBuilder().setColor("#00FF00").setTitle("\u{1F4E8} New ModMail Ticket").setDescription(
        `**User:** ${message.author.tag} (${message.author.id})
**Account Created:** <t:${Math.floor(
          message.author.createdTimestamp / 1e3
        )}:R>`
      ).setThumbnail(message.author.displayAvatarURL()).setTimestamp();
      await ticketChannel.send({ embeds: [welcomeEmbed] });
      await message.react("\u2705");
    } catch (error) {
      logger.error("Error creating ticket:", {
        error: error instanceof Error ? error.message : String(error)
      });
      await message.reply("\u274C Failed to create ticket. Please contact an administrator.");
      return;
    }
  }
  const embed = new import_discord4.EmbedBuilder().setColor("#0099FF").setAuthor({
    name: message.author.tag,
    iconURL: message.author.displayAvatarURL()
  }).setDescription(message.content || "*[No text content]*").setFooter({ text: `User ID: ${message.author.id}` }).setTimestamp();
  const imageAttachment = message.attachments.find(
    (a) => a.contentType && a.contentType.startsWith("image/")
  );
  if (imageAttachment) {
    embed.setImage(imageAttachment.url);
  }
  const otherAttachments = message.attachments.filter((a) => !a.contentType || !a.contentType.startsWith("image/")).map((a) => a.url);
  try {
    await ticketChannel.send({
      content: message.content,
      // Content outside embed for mentions/previews
      embeds: [embed],
      files: otherAttachments
    });
  } catch (error) {
    logger.error("Error forwarding message:", { error });
  }
}
async function handleStaffReply(message) {
  if (message.content.startsWith("!")) return;
  if (message.channel.type !== import_discord4.ChannelType.GuildText) return;
  const userId = message.channel.topic?.match(/\((\d+)\)/)?.[1];
  if (!userId) return;
  try {
    const user = await message.client.users.fetch(userId);
    const embed = new import_discord4.EmbedBuilder().setColor("#00FF00").setAuthor({
      name: "Staff Reply",
      iconURL: message.author.displayAvatarURL()
    }).setDescription(message.content || "*[No text content]*").setTimestamp();
    const imageAttachment = message.attachments.find(
      (a) => a.contentType && a.contentType.startsWith("image/")
    );
    if (imageAttachment) {
      embed.setImage(imageAttachment.url);
    }
    const otherAttachments = message.attachments.filter((a) => !a.contentType || !a.contentType.startsWith("image/")).map((a) => a.url);
    await user.send({
      content: message.content,
      embeds: [embed],
      files: otherAttachments
    });
    await message.react("\u2705");
  } catch (error) {
    await message.react("\u274C");
    logger.error("Error sending reply to user", {
      error: error instanceof Error ? error.message : String(error)
    });
  }
}

// src/discord/client.ts
function createDiscordClient() {
  const client = new import_discord5.Client({
    intents: [
      import_discord5.GatewayIntentBits.Guilds,
      import_discord5.GatewayIntentBits.GuildMessages,
      import_discord5.GatewayIntentBits.MessageContent,
      import_discord5.GatewayIntentBits.DirectMessages,
      import_discord5.GatewayIntentBits.GuildMembers,
      import_discord5.GatewayIntentBits.GuildVoiceStates,
      import_discord5.GatewayIntentBits.GuildMessageReactions,
      import_discord5.GatewayIntentBits.GuildBans,
      import_discord5.GatewayIntentBits.GuildPresences,
      import_discord5.GatewayIntentBits.GuildInvites
    ],
    partials: [import_discord5.Partials.Channel, import_discord5.Partials.Message]
  });
  client.once(import_discord5.Events.ClientReady, (c) => {
    logger.info(`Ready! Logged in as ${c.user.tag}`);
  });
  client.on(import_discord5.Events.InteractionCreate, async (interaction) => {
    try {
      if (interaction.isChatInputCommand()) {
        await handleSlashCommand(interaction);
      } else if (interaction.isButton()) {
        await handleInteractionCreate(interaction);
      }
    } catch (error) {
      logger.error("Error handling interaction", {
        error: error instanceof Error ? error.message : String(error)
      });
    }
  });
  client.on(import_discord5.Events.MessageCreate, async (message) => {
    try {
      await handleMessageCreate(message);
    } catch (error) {
      logger.error("Error handling message", {
        error: error instanceof Error ? error.message : String(error)
      });
    }
  });
  return client;
}

// src/index.ts
async function main() {
  logger.info("Starting ModMail Bot...");
  await loadCommands();
  startServer().catch((err) => {
    logger.error("Failed to start API server", { error: String(err) });
  });
  try {
    const client = createDiscordClient();
    await client.login(config.discordToken);
  } catch (error) {
    logger.error("Fatal error during startup", {
      error: error instanceof Error ? error.message : String(error)
    });
    process.exit(1);
  }
}
